mapper.select:
SELECT SERIALNO, INSTTYPE, IBF_GET_PARAMNAME('SYSTEM','INSTTYPE',INSTTYPE) AS INSTTYPE_NAME, FUNDID, (SELECT FUNDNM FROM FUNDINFO WHERE ROWNUM = 1 AND FUNDID = T.FUNDID) AS FUND_NAME, APKIND, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) AS APKIND_NAME, STRAMT, ENDAMT, TO_CHAR(DISCOUNT,'FM9999999999999990.00') AS DISCOUNT, STATUS, IBF_GET_PARAMNAME('SYSTEM','ECCDATAST',STATUS) AS STATUS_NAME, CK_STATUS, IBF_GET_PARAMNAME('SYSTEM','ECC_CHECKDATAST',CK_STATUS) AS CHECK_STATUS_NAME, C_MAN AS CREATE_ID, ECC_IBF_GET_EMPLOYEE_NAME(C_MAN) AS CREATE_NAME, TO_CHAR(C_TIME,'YYYY-MM-DD HH24:MI:SS') CREATE_TIME, E_MAN AS MODIFY_ID, ECC_IBF_GET_EMPLOYEE_NAME(E_MAN) AS MODIFY_NAME, TO_CHAR(E_TIME,'YYYY-MM-DD HH24:MI:SS') MODIFY_TIME, CONF_MAN AS CHECK_ID, ECC_IBF_GET_EMPLOYEE_NAME(CONF_MAN) AS CHECK_NAME, TO_CHAR(CONF_TIME,'YYYY-MM-DD HH24:MI:SS') AS CHECK_TIME FROM INST_DISCOUNT T WHERE 1=1
AND SERIALNO = #{sp.serialNo}
AND INSTTYPE = #{sp.instType}
AND APKIND = #{sp.apkind}
AND FUNDID = #{sp.fundId}
ORDER BY CK_STATUS ASC,STATUS DESC

SELECT SERIALNO, INSTTYPE, IBF_GET_PARAMNAME('SYSTEM','INSTTYPE',INSTTYPE) AS INSTTYPE_NAME, FUNDID, (SELECT FUNDNM FROM FUNDINFO WHERE ROWNUM = 1 AND FUNDID = T.FUNDID) AS FUND_NAME, APKIND, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) AS APKIND_NAME, STRAMT, ENDAMT, TO_CHAR(DISCOUNT,'FM9999999999999990.00') AS DISCOUNT, TO_CHAR(C_TIME,'YYYY-MM-DD HH24:MI:SS') CREATE_TIME, STATUS, IBF_GET_PARAMNAME('SYSTEM','ECCDATAST',STATUS) AS STATUS_NAME, CK_STATUS, IBF_GET_PARAMNAME('SYSTEM','ECC_CHECKDATAST',CK_STATUS) AS CHECK_STATUS_NAME, C_MAN AS CREATE_ID, ECC_IBF_GET_EMPLOYEE_NAME(C_MAN) AS CREATE_NAME, TO_CHAR(C_TIME,'YYYY-MM-DD HH24:MI:SS') CREATE_TIME, E_MAN AS MODIFY_ID, ECC_IBF_GET_EMPLOYEE_NAME(E_MAN) AS MODIFY_NAME, TO_CHAR(E_TIME,'YYYY-MM-DD HH24:MI:SS') MODIFY_TIME, CONF_MAN AS CHECK_ID, ECC_IBF_GET_EMPLOYEE_NAME(CONF_MAN) AS CHECK_NAME, TO_CHAR(CONF_TIME,'YYYY-MM-DD HH24:MI:SS') AS CHECK_TIME FROM INST_DISCOUNT T WHERE 1=1
AND SERIALNO = #{sp.serialNo}
AND INSTTYPE = #{sp.instType}
AND APKIND = #{sp.apkind}
AND FUNDID = #{sp.fundId}
ORDER BY CK_STATUS ASC,STATUS DESC
